-- ============================================
-- 00026_suwon_map.sql
-- 수원시 44개 행정동 경계 GeoJSON + region_pledges 연결
--   출처: HangJeongDong_ver202506.json (vuski/admdongkor 계열)
--   44개 동 = 장안구 10 + 권선구 12 + 팔달구 10 + 영통구 12
-- ============================================

create table if not exists public.suwon_map_regions (
  id uuid primary key default gen_random_uuid(),
  gu_code text not null check (gu_code in ('jangan','gwonseon','paldal','yeongtong')),
  gu_name text not null,
  dong_name text not null,
  adm_cd2 text not null unique,
  geojson jsonb not null,
  region_pledge_id uuid references public.region_pledges(id) on delete set null,
  created_at timestamptz default now()
);

create index if not exists idx_suwon_map_regions_gu on public.suwon_map_regions(gu_code);
create index if not exists idx_suwon_map_regions_pledge on public.suwon_map_regions(region_pledge_id);

alter table public.suwon_map_regions enable row level security;

drop policy if exists "public read suwon map" on public.suwon_map_regions;
create policy "public read suwon map"
  on public.suwon_map_regions
  for select
  using (true);

drop policy if exists "admin all suwon map" on public.suwon_map_regions;
create policy "admin all suwon map"
  on public.suwon_map_regions
  for all
  using (
    exists (
      select 1 from public.profiles
      where profiles.id = auth.uid() and profiles.role = 'admin'
    )
  )
  with check (
    exists (
      select 1 from public.profiles
      where profiles.id = auth.uid() and profiles.role = 'admin'
    )
  );

